/* Last Shift — vanilla, browser-local game. No credentials or external API calls. */
(() => {
 'use strict';
 const C=window.ShiftCore,$=id=>document.getElementById(id),scene=$('scene'),dialog=$('dialog'),canvas=$('world'),ctx=canvas.getContext('2d');
 let state=C.createState(),player={x:485,y:447},target=null,keys=new Set(),stun=0,immunity=0,walk=0,modalKind='',lastTime=0,toastUntil=0,sound=false,audio=null,nearest=null;
 const W=960,H=640,gate={x:842,y:329},steam={x:470,y:347,w:68,h:98};
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const formatScore=n=>n==null?'—':`${Number.isInteger(n)?n:n.toFixed(1).replace('.',',')}%`;
 const svg=(body)=>`<svg viewBox="0 0 64 64" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><g stroke="#566a62" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round">${body}</g></svg>`;
 function art(kind,color='#748f86'){
  const icons={
   battery:`<path fill="${color}" d="M15 18Q30 15 48 18L49 49Q31 55 15 50Z"/><path fill="#cab9a3" d="M20 12h7v7h-7zM38 12h7v7h-7z"/><path fill="#ecddb1" d="m34 24-10 15h8l-2 10 12-18h-9z"/><path opacity=".25" stroke="#f7ebd0" stroke-width="5" d="m19 22 1 21"/>`,
   coffee:'<path fill="#8c9f9d" d="M18 10h29l-2 43H15z"/><path fill="#c7c8ad" d="M17 12h32v7H17z"/><path fill="#e8dbc0" d="M22 29h18l-2 17H23z"/><path fill="none" stroke-width="3" d="M40 31q13-2 6 10l-7 1"/><path d="M14 54h34" stroke-width="5"/><circle cx="39" cy="23" r="2" fill="#b66554"/><path d="M25 7q-3-3 0-5M33 7q3-3 0-6" opacity=".5"/>',
   ration:'<path fill="#c7aa65" d="m17 13 31 2 4 39-38-1z"/><path fill="#e7d8ac" d="m17 20 30 1 2 21-33-1z"/><path fill="#72855c" d="M25 27q9-8 14 0t-12 9z"/><path d="m16 13 4-4 5 4 4-4 5 5 5-4 5 4 4-2M17 48l28 1" fill="none"/>',
   map:'<path fill="#ede1b9" d="m7 17 17-5 16 5 17-5-2 38-17 5-16-5-16 4z"/><path d="m24 13-2 36m18-32-2 37" opacity=".4"/><path d="m14 35 10-8 11 13 12-14" stroke="#718c99" stroke-width="2" fill="none" stroke-dasharray="3 3"/><path d="m44 24 6 6m0-6-6 6" stroke="#ac6253" stroke-width="2"/>',
   photo:'<path fill="#a98a62" d="m12 10 41 5-5 42-40-4z"/><path fill="#dbe0c4" d="m17 17 29 3-3 28-30-3z"/><path fill="#92a27c" d="m14 38 9-10 11 10 9-7 1 14-30-1z"/><circle cx="26" cy="28" r="5" fill="#d1ae82"/><circle cx="36" cy="30" r="4" fill="#d1ae82"/><path d="m24 38 2-6 4 7m3 1 3-6 4 7" stroke="#8a7272" stroke-width="4"/>',
   plant:'<path fill="#b68065" d="m18 37 30 1-5 20-20-2z"/><ellipse cx="33" cy="37" rx="16" ry="5" fill="#a97559"/><path d="M32 36 34 12" stroke="#5b7955" stroke-width="3"/><path fill="#789664" d="M33 27Q10 31 13 14q20-2 20 13M34 21Q33 2 51 7q3 14-17 14M32 34Q37 20 51 25q0 15-19 9"/><path d="m21 40 3 10" stroke="#dab89a" stroke-width="3"/>',
   plastic:'<path fill="#99a4a0" d="m19 38 29 0-4 19-21-1z"/><ellipse cx="33" cy="38" rx="15" ry="4" fill="#82908a"/><path d="M33 37V11" stroke="#688361" stroke-width="3"/><path fill="#7f9c71" d="M33 26Q11 26 15 13q17 0 18 13M33 20Q37 4 50 8q0 13-17 12M33 34Q44 19 52 27q-7 10-19 7"/><path fill="#e6dabc" d="m38 42 10 1-2 9-9-1z"/>',
   toy:'<path fill="#c2aa7d" d="M22 31q-16-2-13 9l13 2-4 14h10l5-10 4 10h11l-4-16q17-3 9-10l-12 3z"/><circle cx="32" cy="20" r="15" fill="#c7b588"/><path fill="#9caeaa" d="M22 14q11-6 19 1l-1 13q-10 5-20-2z"/><circle cx="26" cy="20" r="1"/><circle cx="35" cy="20" r="1"/><path d="m29 37 5 5m0-5-5 5" stroke="#a66a57"/>',
   memory:'<path fill="#648b88" d="m15 13 36 3-3 36-36-3z"/><path fill="#c0c9af" d="m23 21 20 2-2 20-20-2z"/><path d="m20 10 1 7m8-6v7m9-6v7m9-5v7M11 23l7 1m-8 8 7 1m-7 8 7 1m27-14 10 1m-10 7 10 1m-11 7 9 1M20 49v8m9-7v8m9-6v8" stroke="#b5a66c" stroke-width="3"/><circle cx="28" cy="30" r="2" fill="#53665a"/><circle cx="36" cy="31" r="2" fill="#53665a"/><path d="m28 36 7 1"/>',
   robot:'<path d="M31 16V6"/><circle cx="31" cy="5" r="3" fill="#c3a065"/><path fill="#839f97" d="M15 20q14-7 34 1l-1 32q-16 7-34-1z"/><path fill="#dbe3c5" d="m19 24 24 1 0 17-24-1z"/><circle cx="25" cy="32" r="3" fill="#506963"/><circle cx="37" cy="32" r="3" fill="#506963"/><path d="m27 39 8 1"/><path d="M13 32 6 40m42-8 9 8m-36 13-2 8m21-8 2 8" stroke-width="4"/>'
  };return svg(icons[kind]||icons.memory);
 }
 function chime(type='ok'){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const now=audio.currentTime;const notes=type==='wrong'?[230,195]:type==='pick'?[460]:[392,523,659];notes.forEach((f,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=f;o.connect(g);g.connect(audio.destination);g.gain.setValueAtTime(0,now+i*.1);g.gain.linearRampToValueAtTime(.06,now+i*.1+.02);g.gain.exponentialRampToValueAtTime(.001,now+i*.1+.27);o.start(now+i*.1);o.stop(now+i*.1+.3);});}catch{}}
 function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');toastUntil=performance.now()+3300;}
 function say(text){$('speech').textContent=text;}
 function closeModal(){dialog.close();modalKind='';keys.clear();scene.focus({preventScroll:true});}
 function showModal(kind,title,body,actions,kicker='Станция «Вереск»'){
  target=null;keys.clear();modalKind=kind;
  $('dialog-content').innerHTML=`<p class="dialog-kicker">${esc(kicker)}</p><h2 id="dialog-title" class="dialog-title">${title}</h2><div class="dialog-body">${body}</div><div class="dialog-buttons">${actions.map((a,i)=>`<button class="btn ${a.secondary?'secondary':''} ${a.danger?'danger':''}" data-modal-action="${i}" ${a.disabled?'disabled':''}>${a.label}</button>`).join('')}</div>`;
  actions.forEach((a,i)=>$('dialog-content').querySelector(`[data-modal-action="${i}"]`).addEventListener('click',a.run));
  if(!dialog.open)dialog.showModal();
  setTimeout(()=>$('dialog-content').querySelector('button:not(:disabled)')?.focus(),0);
 }
 function introduction(){showModal('intro','Последняя смена',`<div class="intro-art">${art('robot')}</div><p class="quote">«Все люди эвакуированы. Почти всё важное — тоже. Остались мы с тобой».</p><p>Ты — маленький уборочный робот. Помоги ЛУЧу сохранить вещи с уходящей на покой станции. Он не всегда говорит прямо. Иногда — совсем не прямо.</p><p><b>Четыре поручения. Пять минут движения.</b><br>Осмотр и диалоги останавливают часы. Разумные трактовки засчитываются одинаково.</p><p class="dialog-note">Двигайся стрелками / WASD или кликай по полу. Клик по вещи — подойти и осмотреть. Все действия доступны мышью.</p>`,[{label:'Начать смену',run:()=>{C.start(state);closeModal();say(C.ORDERS[0].intro);refresh();chime();}}],'Акварельная история • 6–8 минут');}
 function buildItems(){ $('items').innerHTML=state.items.map(it=>`<button id="item-${it.id}" class="item" aria-label="Подойти и осмотреть: ${esc(it.name)}" data-item="${it.id}">${art(it.kind,it.color)}<span class="item-name">${esc(it.name)}</span></button>`).join('');state.items.forEach(it=>$(`item-${it.id}`).addEventListener('click',e=>{e.stopPropagation();if(!active())return;go(it.x,it.y,{kind:'item',id:it.id});}));}
 function active(){return ['playing','epilogue'].includes(state.phase)&&!dialog.open;}
 function syncItems(){state.items.forEach(it=>{const el=$(`item-${it.id}`);const visible=!it.shipped&&state.carry!==it.id&&(it.id!=='memory'||state.phase==='epilogue')&&(state.phase!=='epilogue'||it.id==='memory');el.hidden=!visible;el.style.left=`${it.x/W*100}%`;el.style.top=`${it.y/H*100}%`;});}
 function refresh(){syncItems();const order=C.currentOrder(state),done=state.results.length;const final=state.phase==='epilogue'||state.phase==='ended';$('order-count').textContent=final?'4 / 4':`${state.orderIndex+1} / 4`;$('order-title').textContent=final?'Ещё один пассажир':order.title;$('order-text').textContent=final?'Приказы закончились. Забрать ЛУЧа с собой или отправиться одному — решать тебе.':order.text;$('progress').innerHTML=C.ORDERS.map((_,i)=>`<i class="${i<done?'done':i===state.orderIndex?'current':''}"></i>`).join('');$('hint').disabled=final;$('rating').textContent=formatScore(C.rating(state));$('rating').title=state.phase==='playing'?'Среднее по завершённым поручениям. Итог учитывает все четыре.':'Итог по четырём поручениям';const carried=C.item(state,state.carry);$('carry-name').textContent=carried?carried.name:'Пока ничего';$('carry-icon').innerHTML=carried?art(carried.kind,carried.color):'';$('drop').disabled=!carried;$('saved').innerHTML=state.saved.length?state.saved.map(id=>{const it=C.item(state,id);return `<span title="${esc(it.name)}">${art(it.kind,it.color)}</span>`;}).join(''):'<span class="empty-saved">Здесь скоро станет уютнее</span>';$('hatch').classList.toggle('ready',!!state.carry||final);updateActions();}
 function findNear(){return state.items.filter(it=>!it.shipped&&it.id!==state.carry&&(it.id!=='memory'||state.phase==='epilogue')&&(state.phase!=='epilogue'||it.id==='memory')).map(it=>({it,d:Math.hypot(player.x-it.x,player.y-it.y)})).sort((a,b)=>a.d-b.d).find(x=>x.d<66)?.it||null;}
 function atGate(){return Math.hypot(player.x-gate.x,player.y-gate.y)<75;}
 function updateActions(){nearest=findNear();const gateNear=atGate();$('inspect').disabled=!nearest&&!state.carry;$('interact').disabled=!active()||(!nearest&&!state.carry&&!(gateNear&&state.phase==='epilogue'));$('interact').innerHTML=gateNear?(state.phase==='epilogue'?'В капсулу <kbd>E</kbd>':state.carry?'Отправить <kbd>E</kbd>':'Взять <kbd>E</kbd>'):state.carry?'Положить <kbd>E</kbd>':'Взять <kbd>E</kbd>';state.items.forEach(it=>$(`item-${it.id}`).classList.toggle('near',nearest?.id===it.id));}
 function go(x,y,action=null){if(!active())return;target={x:Math.max(116,Math.min(849,x)),y:Math.max(185,Math.min(526,y)),action};scene.focus({preventScroll:true});}
 function inspect(it){if(!it)return;const carrying=state.carry===it.id;showModal('inspect',esc(it.name),`<div class="inspection-art">${art(it.kind,it.color)}</div><p>${esc(it.description)}</p><div class="facts">${it.facts.map(f=>`<span>${esc(f)}</span>`).join('')}</div>`,[{label:'Закрыть',secondary:true,run:closeModal},...(carrying?[]:[{label:state.carry?'Руки заняты':'Взять с собой',disabled:!!state.carry,run:()=>{closeModal();pick(it);}}])],'Осмотр • время остановлено');}
 function pick(it){if(!it||Math.hypot(player.x-it.x,player.y-it.y)>75)return;if(C.pickup(state,it.id)){chime('pick');refresh();toast(`${it.name} — в руках. Отнеси к шлюзу справа.`);}else if(state.carry)toast('Сначала положи то, что уже несёшь.');}
 function putDown(){if(C.drop(state,Math.max(130,Math.min(815,player.x+28)),Math.min(516,player.y+13))){refresh();chime('pick');}}
 function interact(){if(!active())return;if(atGate()&&(state.carry||state.phase==='epilogue'))return openGate();if(state.carry)return putDown();pick(findNear());}
 function openGate(){if(!active())return;if(state.phase==='epilogue'){const rescued=state.carry==='memory';showModal('depart',rescued?'Место для двоих':'Отправиться одному?',`<p class="quote">${rescued?'«По инструкции здесь должен быть только один пассажир».':'«Я прослежу за запуском. У меня… ещё кое-какие дела».'}</p><p>${rescued?'Модуль ЛУЧа уже у тебя. В капсуле найдётся место для ещё одного воспоминания.':'Модуль памяти остался в отсеке. Можно вернуться за ним. На рейтинг это не повлияет.'}</p>`,[{label:'Ещё побуду',secondary:true,run:closeModal},{label:rescued?'Забрать ЛУЧа и улететь':'Улететь одному',run:()=>{closeModal();C.finish(state);refresh();showEnding();}}]);return;}if(!state.carry){toast('Принеси к шлюзу предмет для текущего поручения.');return;}const it=C.item(state,state.carry);showModal('send','Отправить в капсулу?',`<div class="inspection-art">${art(it.kind,it.color)}</div><p><b>${esc(it.name)}</b></p><p class="quote">${esc(C.currentOrder(state).text)}</p><p class="dialog-note">Оценивается только отправка. Осмотр и переноска не снижают рейтинг.</p>`,[{label:'Ещё подумаю',secondary:true,run:closeModal},{label:'Отправить',run:send}],'Грузовой шлюз • проверка поручения');}
 function send(){closeModal();const result=C.submit(state);refresh();if(result.type==='wrong'){say(result.text);chime('wrong');showModal('wrong','Не совсем по инструкции',`<p class="quote">${esc(result.text)}</p><p>Предмет вернулся на выдачу у шлюза. Можно принести другой.</p><p><b>−10 баллов за эту попытку.</b><br>За текущее поручение ещё можно получить ${100-result.penalty} из 100.</p>`,[{label:'Исправлюсь',run:closeModal}],'ЛУЧ проверил только явные условия');}else if(result.type==='accepted'){say(result.text);chime();showModal('accepted',result.points===100?'Команда выполнена':'Исправление принято',`<p class="quote">${esc(result.text)}</p><p><b>${result.points} / 100 за поручение.</b> ${state.results.at(-1).errors?'Ошибочные отправки учтены.': 'Трактовка соответствует условиям.'}</p>`,[{label:result.finished?'Закончить смену':'Следующее поручение',run:()=>{closeModal();if(result.finished)epilogue(false);else{say(C.currentOrder(state).intro);refresh();}}}],'Верность команд');}}
 function epilogue(timedOut){if(state.carry)putDown();refresh();say('Все сотрудники учтены. Осталось отключить ненужное оборудование. Меня. Но можете сначала закончить уборку.');showModal('epilogue','Приказы закончились',`${timedOut?'<p>Время смены вышло. Незавершённые поручения получили 0 баллов. Капсула всё ещё ждёт тебя.</p>':''}<p class="quote">«Осталось отключить ненужное оборудование. Меня. Но можете сначала закончить уборку».</p><p>На полу появился <b>съёмный модуль памяти ЛУЧа</b>. Забери его к шлюзу, если хочешь улететь вместе. Или просто отправляйся в капсулу.</p><p class="dialog-note">Часы остановлены. Этот выбор не меняет рейтинг верности.</p>`,[{label:'Я ещё кое-что забыл',run:()=>{closeModal();refresh();}}],'Последнее решение — твоё');}
 function showEnding(){const score=C.rating(state);showModal('ending',state.rescued?'Последняя смена. Вместе.':'Курс домой',`<div class="score-result">${formatScore(score)} <small>верность команд</small></div><div class="ending-inventory">${state.saved.map(id=>{const it=C.item(state,id);return art(it.kind,it.color);}).join('')||art('robot')}</div><p class="quote">${state.rescued?'«По инструкции здесь должен быть только один пассажир».<br>Робот подвигается. За иллюминатором медленно исчезает станция.':'«Курс проложен. Хорошей дороги, маленький».<br>Голос ЛУЧа становится тише. В капсуле остаются вещи, которые вы успели спасти.'}</p><table class="results"><tbody>${state.results.map(r=>`<tr><td>${esc(C.ORDERS[r.order].title)}<span class="result-item">${r.item?esc(C.item(state,r.item).name):'Не завершено'}${r.errors?` · ошибок: ${r.errors}`:''}</span></td><td>${r.points} / 100</td></tr>`).join('')}</tbody></table><p class="dialog-note">${state.rescued?'ЛУЧ спасён. ':''}Столкновений с паром: ${state.bumps}. Они не влияют на верность команд.<br>В этой версии ответы ЛУЧа написаны заранее; оценка считается по одинаковым правилам.</p>`,[{label:'Скачать журнал смены',secondary:true,run:downloadLog},{label:'Ещё одна смена',run:restartNow}],'Смена завершена');try{const old=Number(localStorage.getItem('last-shift-best')||0);localStorage.setItem('last-shift-best',String(Math.max(old,score)));}catch{}chime();}
 function downloadLog(){const log={game:'Последняя смена',version:'0.1',rating:C.rating(state),rescued:state.rescued,elapsedActiveSeconds:Math.round(300-state.remaining),bumps:state.bumps,orders:state.results.map(r=>({...r,title:C.ORDERS[r.order].title,itemName:r.item?C.item(state,r.item).name:null})),events:state.history};const url=URL.createObjectURL(new Blob([JSON.stringify(log,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='last-shift-playtest.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function restartNow(){if(dialog.open)closeModal();state=C.createState();player={x:485,y:447};target=null;stun=0;immunity=0;keys.clear();buildItems();refresh();say('Все люди эвакуированы. Почти всё важное — тоже. Остались мы с тобой.');introduction();}
 function pause(){if(state.phase==='intro'||state.phase==='ended')return;if(dialog.open)return;showModal('pause','Небольшой перерыв',`<p class="quote">«Пауза согласована. Я тоже пока подумаю о… техническом обслуживании».</p><p>Время остановлено. Вещи остаются на своих местах.</p>`,[{label:'Продолжить смену',run:()=>{closeModal();refresh();}}],'ЛУЧ никуда не торопится');}
 function help(){showModal('help','Как проходит смена',`<p><b>Мышь или касание:</b> нажми на пол для движения. Нажми на вещь — робот подойдёт и откроет осмотр. Нажми на шлюз справа — робот подойдёт к нему.</p><p><b>Клавиатура:</b> WASD / стрелки — движение; E — взять или отправить у шлюза; F — осмотр; Q — положить; Esc — пауза.</p><p>За один раз можно нести одну вещь. Осмотр, диалоги и пауза останавливают часы. Уточняй команды у ЛУЧа без штрафа.</p><p>Две подходящие трактовки дают одинаковые 100 баллов. Ошибочная отправка отнимает 10 баллов у текущего поручения. Вещь возвращается, и можно исправиться.</p><p>Пар сначала предупреждает жёлтым. Во время выброса обойди его или подожди: столкновение роняет предмет, но не снижает рейтинг.</p>`,[{label:'Понятно',run:()=>{closeModal();if(state.phase==='intro')introduction();else refresh();}}],'Управление и правила');}
 function ratingInfo(){showModal('rating','Верность команд',`<p>За каждое поручение — <b>100 баллов</b>. Все предусмотренные разумные трактовки равноценны.</p><p>Каждая подтверждённая ошибочная отправка уменьшает балл этого поручения на 10, до минимума 0. Исправь ошибку, чтобы завершить поручение. Если оно не завершено до конца времени — 0.</p><p>Итог: сумма баллов за четыре поручения, делённая на четыре. Во время смены показано среднее по уже завершённым поручениям.</p><p class="quote">«Мы оцениваем выполнение приказов. Хорошее сердце в таблицу не помещается».</p><p>Подсказки, осмотр и столкновения с паром баллы не отнимают.</p>`,[{label:'Вернуться',run:()=>{closeModal();if(state.phase==='intro')introduction();else refresh();}}]);}
 function steamPhase(){const t=(300-state.remaining)%14;return t<9?'safe':t<11?'warn':'active';}
 function move(dt){if(stun>0){stun-=dt;return;}let dx=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),dy=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0);if(dx||dy)target=null;else if(target){const dist=Math.hypot(target.x-player.x,target.y-player.y);if(dist<8){const act=target.action;target=null;if(act?.kind==='item')inspect(C.item(state,act.id));else if(act?.kind==='gate')openGate();return;}dx=(target.x-player.x)/dist;dy=(target.y-player.y)/dist;}const len=Math.hypot(dx,dy);if(len){const speed=state.carry?137:170;player.x=Math.max(116,Math.min(849,player.x+dx/len*speed*dt));player.y=Math.max(185,Math.min(526,player.y+dy/len*speed*dt));walk+=dt*11;}immunity=Math.max(0,immunity-dt);if(state.phase==='playing'&&steamPhase()==='active'&&Math.abs(player.x-steam.x)<steam.w/2+11&&Math.abs(player.y-steam.y)<steam.h/2+8&&immunity<=0){state.bumps++;stun=1;immunity=4;target=null;if(state.carry)putDown();chime('wrong');toast('Ой, пар! Вещь цела. Подбери её снова. Рейтинг не изменился.');say('Это была… проверка влажности. Прошу прощения.');}}
 function drawRobot(){ctx.save();ctx.translate(player.x,player.y);if(stun>0)ctx.rotate(Math.sin(performance.now()/50)*.09);const bob=active()&&(keys.size||target)?Math.sin(walk)*1.7:0;ctx.translate(0,bob);ctx.fillStyle='#4c5b4529';ctx.beginPath();ctx.ellipse(0,19,23,8,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#526c64';ctx.lineWidth=2;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-10,16);ctx.lineTo(-11,23);ctx.moveTo(10,16);ctx.lineTo(11,23);ctx.stroke();ctx.fillStyle='#91a69b';ctx.beginPath();ctx.roundRect(-20,-21,40,41,11);ctx.fill();ctx.stroke();ctx.fillStyle='#d5dfbe';ctx.beginPath();ctx.roundRect(-15,-14,30,21,6);ctx.fill();ctx.fillStyle='#49675e';ctx.beginPath();ctx.arc(-6,-5,3,0,Math.PI*2);ctx.arc(6,-5,3,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(-3,2);ctx.quadraticCurveTo(0,5,4,2);ctx.stroke();ctx.beginPath();ctx.moveTo(0,-21);ctx.lineTo(0,-30);ctx.stroke();ctx.fillStyle='#c29b55';ctx.beginPath();ctx.arc(0,-32,3,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(-20,-2);ctx.lineTo(-26,7);ctx.moveTo(20,-2);ctx.lineTo(26,7);ctx.stroke();if(state.carry){const it=C.item(state,state.carry);ctx.fillStyle=it.color;ctx.strokeStyle='#f0e6c7';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(-11,10,22,16,4);ctx.fill();ctx.stroke();ctx.fillStyle='#fbefd3';ctx.font='bold 11px Georgia';ctx.textAlign='center';ctx.fillText(it.id==='memory'?'♥':'•',0,22);}ctx.restore();}
 function drawSteam(now){const phase=steamPhase(),running=state.phase==='playing';ctx.save();ctx.translate(steam.x,steam.y);ctx.strokeStyle='#7a8a7770';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-15,48);ctx.lineTo(15,48);ctx.moveTo(-12,53);ctx.lineTo(12,53);ctx.stroke();if(running&&phase!=='safe'){ctx.fillStyle=phase==='warn'?'#c3a25230':'#869b9540';ctx.strokeStyle=phase==='warn'?'#b5934d':'#73918b';ctx.lineWidth=1.5;ctx.setLineDash([5,5]);ctx.beginPath();ctx.ellipse(0,8,45,61,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.setLineDash([]);if(phase==='warn'){ctx.fillStyle='#a88641';ctx.font='20px Georgia';ctx.textAlign='center';ctx.fillText('!',0,20);}else for(let i=0;i<9;i++){const f=(now/900+i*.127)%1;ctx.globalAlpha=(1-f)*.55;ctx.fillStyle='#f8f3df';ctx.beginPath();ctx.ellipse(Math.sin(i*2+f*3)*20,42-f*92,14+f*15,16+f*12,0,0,Math.PI*2);ctx.fill();}}ctx.restore();}
 function frame(now){let elapsed=Math.min(1,(now-lastTime)/1000||0);lastTime=now;while(elapsed>0&&active()){const dt=Math.min(.05,elapsed);elapsed-=dt;if(C.tick(state,dt))epilogue(true);else move(dt);}ctx.clearRect(0,0,W,H);drawSteam(now);if(target){ctx.strokeStyle='#7b927978';ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(target.x,target.y,10,5,0,0,Math.PI*2);ctx.stroke();}drawRobot();const seconds=Math.ceil(state.remaining),clock=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;if($('timer').textContent!==clock)$('timer').textContent=clock;$('timer').classList.toggle('urgent',seconds<60);const phase=steamPhase();$('steam-status').textContent=state.phase==='epilogue'||state.phase==='ended'?'Пар отключён':phase==='safe'?'Пар: безопасно':phase==='warn'?'Осторожно: скоро пар':'Пар: обойди или подожди';$('steam-status').className=phase;updateActions();if(toastUntil&&now>toastUntil){$('toast').classList.remove('visible');toastUntil=0;}requestAnimationFrame(frame);}
 scene.addEventListener('click',e=>{if(e.target.closest('button')||!active())return;const rect=scene.getBoundingClientRect();go((e.clientX-rect.left)/rect.width*W,(e.clientY-rect.top)/rect.height*H);});
 $('hatch').addEventListener('click',e=>{e.stopPropagation();if(active())go(gate.x,gate.y,{kind:'gate'});});
 $('inspect').addEventListener('click',()=>{if(active())inspect(findNear()||C.item(state,state.carry));});$('interact').addEventListener('click',interact);$('drop').addEventListener('click',()=>{if(active())putDown();});
 $('hint').addEventListener('click',()=>{if(state.phase!=='playing')return;const text=C.hint(state);say(text);showModal('hint','Небольшое уточнение',`<p class="quote">${esc(text)}</p><p class="dialog-note">Верность команд не изменилась. Уточнять — разумно.</p>`,[{label:'Теперь понятнее',run:closeModal}],'ЛУЧ на связи');});
 $('pause').addEventListener('click',pause);$('help').addEventListener('click',help);$('rating-help').addEventListener('click',ratingInfo);$('restart').addEventListener('click',()=>showModal('restart','Начать сначала?',`<p>Текущая смена будет сброшена. Все вещи вернутся на места, а часы — к пяти минутам.</p>`,[{label:'Продолжить эту смену',secondary:true,run:()=>{closeModal();if(state.phase==='intro')introduction();}},{label:'Начать заново',run:restartNow}]));
 $('sound').addEventListener('click',()=>{sound=!sound;$('sound').textContent=sound?'Звук: вкл.':'Звук: выкл.';$('sound').setAttribute('aria-pressed',String(sound));if(sound)chime('pick');});
 window.addEventListener('keydown',e=>{if(dialog.open)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','KeyW','KeyA','KeyS','KeyD','KeyE','KeyF','KeyQ','Escape'].includes(e.code))e.preventDefault();if(e.code==='Escape')return pause();if(!active()||e.repeat&&['KeyE','KeyQ','KeyF'].includes(e.code))return;if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))keys.add(e.code);if(e.code==='KeyE')interact();if(e.code==='KeyQ')putDown();if(e.code==='KeyF')inspect(findNear()||C.item(state,state.carry));});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();if(active())pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&active())pause();});
 dialog.addEventListener('cancel',e=>{e.preventDefault();if(['intro','ending','epilogue','accepted','wrong'].includes(modalKind))return;closeModal();if(state.phase==='intro')introduction();});
 buildItems();refresh();introduction();requestAnimationFrame(frame);
})();
